guidance.correct_example:
def fetch(a_url: str) -> Result[str]:
    b_continue = True
    result: Result[str] = INVALID_RESULT
    try:
        response = requests.get(a_url, timeout=30)
    except requests.Timeout as e:
        logger.error('Request timed out', url=a_url, error=str(e))
        result = Result.failure(f'Request timed out: {e}')
        b_continue = False
    if b_continue:
        result = Result.success(response.text)
    return result

